func (this *Upbit) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades
	//
	//       {             market: "BTC-ETH",
	//             "trade_date_utc": "2018-11-22",
	//             "trade_time_utc": "13:55:24",
	//                  "timestamp":  1542894924397,
	//                "trade_price":  0.02914289,
	//               "trade_volume":  0.20074397,
	//         "prev_closing_price":  0.02966,
	//               "change_price":  -0.00051711,
	//                    "ask_bid": "ASK",
	//              "sequential_id":  15428949259430000 }
	//
	// fetchOrder trades
	//
	//         {
	//             "market": "KRW-BTC",
	//             "uuid": "78162304-1a4d-4524-b9e6-c9a9e14d76c3",
	//             "price": "101000.0",
	//             "volume": "0.77368323",
	//             "funds": "78142.00623",
	//             "ask_fee": "117.213009345",
	//             "bid_fee": "117.213009345",
	//             "created_at": "2018-04-05T14:09:15+09:00",
	//             "side": "bid",
	//         }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var id any = this.SafeString2(trade, "sequential_id", "uuid")
	var orderId any = nil
	var timestamp any = this.SafeInteger(trade, "timestamp")
	if IsTrue(IsEqual(timestamp, nil)) {
		timestamp = this.Parse8601(this.SafeString(trade, "created_at"))
	}
	var side any = nil
	var askOrBid any = this.SafeStringLower2(trade, "ask_bid", "side")
	if IsTrue(IsEqual(askOrBid, "ask")) {
		side = "sell"
	} else if IsTrue(IsEqual(askOrBid, "bid")) {
		side = "buy"
	}
	var cost any = this.SafeString(trade, "funds")
	var price any = this.SafeString2(trade, "trade_price", "price")
	var amount any = this.SafeString2(trade, "trade_volume", "volume")
	var marketId any = this.SafeString2(trade, "market", "code")
	market = this.SafeMarket(marketId, market, "-")
	var fee any = nil
	var feeCost any = this.SafeString(trade, Add(askOrBid, "_fee"))
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"currency": GetValue(market, "quote"),
			"cost":     feeCost,
		}
	}
	return this.SafeTrade(map[string]any{
		"id":           id,
		"info":         trade,
		"order":        orderId,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       GetValue(market, "symbol"),
		"type":         nil,
		"side":         side,
		"takerOrMaker": nil,
		"price":        price,
		"amount":       amount,
		"cost":         cost,
		"fee":          fee,
	}, market)
}

