func (this *Upbit) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits, fetchDeposit
	//
	//     {
	//         "type": "deposit",
	//         "uuid": "94332e99-3a87-4a35-ad98-28b0c969f830",
	//         "currency": "KRW",
	//         "txid": "9e37c537-6849-4c8b-a134-57313f5dfc5a",
	//         "state": "ACCEPTED",
	//         "created_at": "2017-12-08T15:38:02+09:00",
	//         "done_at": "2017-12-08T15:38:02+09:00",
	//         "amount": "100000.0",
	//         "fee": "0.0"
	//     }
	//
	// fetchWithdrawals, fetchWithdrawal
	//
	//     {
	//         "type": "withdraw",
	//         "uuid": "9f432943-54e0-40b7-825f-b6fec8b42b79",
	//         "currency": "BTC",
	//         "txid": "cd81e9b45df8da29f936836e58c907a106057e454a45767a7b06fcb19b966bba",
	//         "state": "processing",
	//         "created_at": "2018-04-13T11:24:01+09:00",
	//         "done_at": null,
	//         "amount": "0.01",
	//         "fee": "0.0",
	//         "krw_amount": "80420.0"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var address any = nil // not present in the data structure received from the exchange
	var tag any = nil     // not present in the data structure received from the exchange
	var updatedRaw any = this.SafeString(transaction, "done_at")
	var timestamp any = this.Parse8601(this.SafeString(transaction, "created_at", updatedRaw))
	var typeVar any = this.SafeString(transaction, "type")
	if IsTrue(IsEqual(typeVar, "withdraw")) {
		typeVar = "withdrawal"
	}
	var currencyId any = this.SafeString(transaction, "currency")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "uuid"),
		"currency":    code,
		"amount":      this.SafeNumber(transaction, "amount"),
		"network":     nil,
		"address":     address,
		"addressTo":   nil,
		"addressFrom": nil,
		"tag":         tag,
		"tagTo":       nil,
		"tagFrom":     nil,
		"status":      this.ParseTransactionStatus(this.SafeStringLower(transaction, "state")),
		"type":        typeVar,
		"updated":     this.Parse8601(updatedRaw),
		"txid":        this.SafeString(transaction, "txid"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"internal":    nil,
		"comment":     nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.SafeNumber(transaction, "fee"),
		},
	}
}
func (this *Upbit) ParseOrderStatus(status any) any {
	var statuses map[string]any = map[string]any{
		"wait":   "open",
		"done":   "closed",
		"cancel": "canceled",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Upbit) ParseOrder(order any, optionalArgs ...any) any {
	// {
	//   "market": "KRW-USDT",
	//   "uuid": "3b67e543-8ad3-48d0-8451-0dad315cae73",
	//   "side": "ask",
	//   "ord_type": "market",
	//   "state": "done",
	//   "created_at": "2025-08-09T16:44:00+09:00",
	//   "volume": "5.377594",
	//   "remaining_volume": "0",
	//   "executed_volume": "5.377594",
	//   "reserved_fee": "0",
	//   "remaining_fee": "0",
	//   "paid_fee": "3.697095875",
	//   "locked": "0",
	//   "prevented_volume": "0",
	//   "prevented_locked": "0",
	//   "trades_count": 1,
	//   "trades": [
	//     {
	//       "market": "KRW-USDT",
	//       "uuid": "795dff29-bba6-49b2-baab-63473ab7931c",
	//       "price": "1375",
	//       "volume": "5.377594",
	//       "funds": "7394.19175",
	//       "trend": "down",
	//       "created_at": "2025-08-09T16:44:00.597751+09:00",
	//       "side": "ask"
	//     }
	//   ]
	// }
	//
	// fetchOpenOrders, fetchClosedOrders, fetchCanceledOrders
	//
	//     {
	//         "uuid": "637fd66-d019-4d77-bee6-8e0cff28edd9",
	//         "side": "ask",
	//         "ord_type": "limit",
	//         "price": "1.5",
	//         "state": "wait",
	//         "market": "SGD-XRP",
	//         "created_at": "2024-06-05T09:37:10Z",
	//         "volume": "10",
	//         "remaining_volume": "10",
	//         "reserved_fee": "0",
	//         "remaining_fee": "0",
	//         "paid_fee": "0",
	//         "locked": "10",
	//         "executed_volume": "0",
	//         "executed_funds": "0",
	//         "trades_count": 0,
	//         "time_in_force": "ioc"
	//     }
	//
	//     {
	//        uuid: '63b38774-27db-4439-ac20-1be16a24d18e',
	//        side: 'bid',
	//        ord_type: 'limit',
	//        price: '100000000',
	//        state: 'wait',
	//        market: 'KRW-BTC',
	//        created_at: '2025-04-01T15:30:47+09:00',
	//        volume: '0.00008',
	//        remaining_volume: '0.00008',
	//        reserved_fee: '4',
	//        remaining_fee: '4',
	//        paid_fee: '0',
	//        locked: '8004',
	//        executed_volume: '0',
	//        trades_count: '0',
	//        identifier: '21',
	//        new_order_uuid: 'cb1cce56-6237-4a78-bc11-4cfffc1bb4c2',
	//        new_order_identifier: '22'
	//      }
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var id any = this.SafeString(order, "uuid")
	var side any = this.SafeStringLower(order, "side")
	if IsTrue(IsEqual(side, "bid")) {
		side = "buy"
	} else if IsTrue(IsEqual(side, "ask")) {
		side = "sell"
	}
	var identifier any = this.SafeString(order, "identifier")
	var typeVar any = this.SafeString(order, "ord_type")
	var timestamp any = this.Parse8601(this.SafeString(order, "created_at"))
	var status any = this.ParseOrderStatus(this.SafeString(order, "state"))
	var lastTradeTimestamp any = nil
	var price any = this.SafeString(order, "price")
	var amount any = this.SafeString(order, "volume")
	var remaining any = this.SafeString(order, "remaining_volume")
	var filled any = this.SafeString(order, "executed_volume")
	var cost any = nil
	if IsTrue(IsEqual(typeVar, "price")) {
		typeVar = "market"
		cost = price
		price = nil
	}
	var average any = nil
	var fee any = nil
	var feeCost any = this.SafeString(order, "paid_fee")
	var marketId any = this.SafeString(order, "market")
	market = this.SafeMarket(marketId, market)
	var trades any = this.SafeValue(order, "trades", []any{})
	trades = this.ParseTrades(trades, market, nil, nil, map[string]any{
		"order": id,
		"type":  typeVar,
	})
	var numTrades int = GetArrayLength(trades)
	if IsTrue(IsGreaterThan(numTrades, 0)) {
		// the timestamp in fetchOrder trades is missing
		lastTradeTimestamp = GetValue(GetValue(trades, Subtract(numTrades, 1)), "timestamp")
		var getFeesFromTrades bool = false
		if IsTrue(IsEqual(feeCost, nil)) {
			getFeesFromTrades = true
			feeCost = "0"
		}
		cost = "0"
		for i := 0; IsLessThan(i, numTrades); i++ {
			var trade any = GetValue(trades, i)
			cost = Precise.StringAdd(cost, this.SafeString(trade, "cost"))
			if IsTrue(getFeesFromTrades) {
				var tradeFee any = this.SafeValue(GetValue(trades, i), "fee", map[string]any{})
				var tradeFeeCost any = this.SafeString(tradeFee, "cost")
				if IsTrue(!IsEqual(tradeFeeCost, nil)) {
					feeCost = Precise.StringAdd(feeCost, tradeFeeCost)
				}
			}
		}
		average = Precise.StringDiv(cost, filled)
	}
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"currency": GetValue(market, "quote"),
			"cost":     feeCost,
		}
	}
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      identifier,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": lastTradeTimestamp,
		"symbol":             GetValue(market, "symbol"),
		"type":               typeVar,
		"timeInForce":        this.SafeStringUpper(order, "time_in_force"),
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               this.ParseNumber(cost),
		"average":            this.ParseNumber(average),
		"amount":             amount,
		"filled":             filled,
		"remaining":          remaining,
		"status":             status,
		"fee":                fee,
		"trades":             trades,
	})
}

